import 'dart:convert';import 'package:flutter/foundation.dart';import 'package:http/http.dart' as http;import 'package:shared_preferences/shared_preferences.dart';import '../models/user_model.dart';class AuthService {  static const String baseUrl = 'http://103.207.168.245/safl/api';  static const String userUrl = 'http://103.207.168.245/safl/api/users';  static Future<UserModel?>? _refreshFuture;  static DateTime? _lastRefreshTime;  static Future<void> updateOnlineStatus(bool isOnline) async {    try {      final prefs = await SharedPreferences.getInstance();      final token = prefs.getString('api_token');      if (token == null) return;      await http.post(        Uri.parse('http://103.207.168.245/safl/api/location/update'),        headers: {          'Content-Type': 'application/json',          'Accept': 'application/json',          'Authorization': 'Bearer $token',        },        body: jsonEncode({          'is_online': isOnline ? 1 : 0,          'login_status': isOnline ? 'login' : 'logout',          'status': isOnline ? 'active' : 'inactive',          'last_seen': DateTime.now().toIso8601String(),        }),      );    } catch (e) {      debugPrint("Status Update Error: $e");    }  }  static Future<UserModel?> getUserData({bool forceRefresh = false}) async {    try {      final prefs = await SharedPreferences.getInstance();      final token = prefs.getString('api_token');      final cachedJson = prefs.getString('user_data');            Map<String, dynamic>? currentUserMap;      if (cachedJson != null) {        try {          final decoded = jsonDecode(cachedJson);          if (decoded is Map) {            currentUserMap = Map<String, dynamic>.from(decoded);          }        } catch (e) {          debugPrint("Error decoding cached user: $e");        }      }      // If we have cached data, return it immediately to avoid UI delay      UserModel? cachedUser;      if (currentUserMap != null) {        cachedUser = UserModel.fromJson(currentUserMap);        if (!forceRefresh) {          // Trigger background refresh only if it's been more than 5 minutes          if (_lastRefreshTime == null ||               DateTime.now().difference(_lastRefreshTime!).inMinutes >= 5) {            _getRefreshFuture(token, currentUserMap);          }          return cachedUser;        }      }      if (token == null) return cachedUser;      return await _getRefreshFuture(token, currentUserMap);    } catch (e) {      debugPrint('getUserData Error: $e');    }    return null;  }  static Future<UserModel?> _getRefreshFuture(String? token, Map<String, dynamic>? currentUserMap) {    if (token == null) return Future.value(null);    if (_refreshFuture != null) return _refreshFuture!;    _refreshFuture = _refreshUserData(token, currentUserMap).then((user) {      _refreshFuture = null; // Reset for next time      if (user != null) {        _lastRefreshTime = DateTime.now();      }      return user;    }).catchError((e) {      _refreshFuture = null;      throw e;    });    return _refreshFuture!;  }  static Future<UserModel?> _refreshUserData(String token, Map<String, dynamic>? currentUserMap) async {    try {      final prefs = await SharedPreferences.getInstance();      debugPrint("Refreshing user data from API...");      final response = await http.get(        Uri.parse(userUrl),        headers: {          'Accept': 'application/json',          'Authorization': 'Bearer $token',        },      ).timeout(const Duration(seconds: 15));      if (response.statusCode == 200) {        final decoded = jsonDecode(response.body);        Map<String, dynamic>? targetUserJson;                // Handle various response structures (List, Map with 'data', etc.)        dynamic listData;        if (decoded is List) {          listData = decoded;        } else if (decoded is Map) {          if (decoded['data'] is List) {            listData = decoded['data'];          } else if (decoded['data'] is Map && decoded['data']['data'] is List) {            listData = decoded['data']['data'];          } else if (decoded['users'] is List) {            listData = decoded['users'];          } else if (decoded['id'] != null) {            // It's a single user object            targetUserJson = Map<String, dynamic>.from(decoded);          }        }        if (listData is List && listData.isNotEmpty) {          final String loginIdStr = currentUserMap?['id']?.toString().trim() ?? "";          final String loginName = currentUserMap?['name']?.toString().trim().toLowerCase() ?? "";                    debugPrint("Searching for Match: ID=$loginIdStr, Name=$loginName in list of ${listData.length}");                    try {            final found = listData.firstWhere(              (u) {                final uid = u['id']?.toString().trim();                final uname = (u['name'] ?? u['exe_name'] ?? '').toString().trim().toLowerCase();                return uid == loginIdStr || (loginName.isNotEmpty && uname == loginName);              },              orElse: () => null            );            if (found != null) {              targetUserJson = Map<String, dynamic>.from(found);              debugPrint("Profile Found and Synced. Role: ${targetUserJson['role'] ?? targetUserJson['position']}");            } else {              debugPrint("No match found in user list for $loginName");            }          } catch (e) {            debugPrint("Matching error: $e");          }        }        if (targetUserJson != null) {          await prefs.setString('user_data', jsonEncode(targetUserJson));          return UserModel.fromJson(targetUserJson);        }      } else {        debugPrint("User Data Refresh Failed: Status ${response.statusCode}");      }    } catch (e) {      debugPrint("Background refresh error: $e");    }    return null;  }}